from pathlib import Path
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]
css=(ROOT/'GIT/web-design-v27.css').read_text()
# Relevant declarations from web-style, evolution, lxp-v2 and design-v22; not the full app.
legacy='''*{box-sizing:border-box}body{margin:0;font:16px/1.5 Segoe UI,Arial,sans-serif;background:#112a55}label{display:block;font-size:14px;font-weight:600;margin:13px 0 4px}input,select,textarea{padding:10px 12px;border:1px solid #adbfca;border-radius:7px;background:white;width:100%}button{color:inherit;background:white;border:1px solid #dce6ec;padding:9px 15px;border-radius:9px;font-weight:600}h2,p{margin:0 0 10px}dialog{width:min(840px,96vw);max-height:91dvh;padding:clamp(20px,3vw,36px);border:1px solid #d9eaf8;border-radius:22px}dialog::backdrop{background:#092957a3}body:has(#app .shell[data-la22-route]) #modal{background:#f4f9ff url('/design-v22/canvas-claro.webp') center/cover;border:1px solid #b9d6f7;border-radius:24px;padding:24px;max-height:92dvh;width:min(900px,96vw);color:#081d50}body:has(#app .shell[data-la22-route]) #modal[data-la22-modal=player]{width:min(1500px,98vw);padding:12px}body:has(#app .shell[data-la22-route]) #modal :is(.lxp-panel,.a6-question,.p5-editor,.a6-editor,.professional-fields,.lxp-question){background:#fff;border:1px solid #d5e6fa;border-radius:14px;padding:15px}body:has(#app .shell[data-la22-route]) #modal :is(button.primary,.lxp-btn.primary){background:linear-gradient(105deg,#0739e5,#0070db 68%,#00869d);color:#fff;border-radius:12px}.lxp-page{min-width:0;max-width:1520px;margin:auto;display:grid;gap:22px}.lxp-field{display:block;font-size:12px;color:#477398;font-weight:730;margin:14px 0}.lxp-field span{display:block;margin-bottom:6px}.lxp-field input,.lxp-field select,.lxp-field textarea{display:block;width:100%;font-size:13px;min-height:46px;border:1px solid #cfdfea;padding:12px 13px;border-radius:12px;background:#fff;color:#193e60}.lxp-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:17px;align-items:start}.lxp-form-grid>.lxp-field{margin-top:0}.okr-target [hidden]{display:none!important}.okr-target+.lxp-note{margin:8px 0 16px}.lxp-note{border:1px solid #c5e5fa;background:#f0f9ff;border-radius:15px;padding:17px 20px;color:#265b84}.lxp-heading-actions{display:flex;justify-content:flex-end;align-self:flex-end}.lxp-btn{display:inline-flex;align-items:center;justify-content:center;min-height:43px;border:1px solid #c9e1f4;border-radius:11px;padding:10px 17px;font-size:13px;font-weight:730;background:#fff;color:#2a659c}.lxp-panel{background:#fff;border:1px solid #dfeaf6;border-radius:22px;padding:clamp(20px,2.5vw,30px);min-width:0}.lxp-page .lxp-btn{background:#fff}.lxp-page .lxp-btn.primary{background:#176bc1;color:white}'''
def field(label,name,value='',typ='text'):
 return f'<label class="lxp-field"><span>{label}</span><input type="{typ}" name="{name}" value="{value}" required></label>'
def select(label,name,value):
 return f'<label class="lxp-field"><span>{label}</span><select name="{name}"><option>{value}</option></select></label>'
kr='<fieldset class="lxp-panel" data-okr-kr><legend>Resultado-chave</legend>'+field('Resultado mensurável','krTitle')+field('Unidade','unit')+field('Valor inicial','baseline','0','number')+field('Meta','target','100','number')+field('Peso','weight','1','number')+'<button type="button" class="lxp-btn" data-okr13="remove-kr">Remover resultado</button></fieldset>'
def fixture(scope, num, route=True):
 department='<div data-okr-department'+(' hidden' if scope=='Empresa' else '')+'>'+('' if scope=='Empresa' else select('Departamento','departmentId','Desenvolvimento Humano'))+'</div>'
 return '<div id="app"><div class="shell" '+('data-la22-route="okr"' if route else '')+'></div></div><dialog id="modal" data-la22-modal="form"><div id="modalBody"><section class="lxp-page"><h2>Novo OKR</h2><form id="okr13Form" data-action="new">'+field('Objetivo','title')+'<div class="lxp-form-grid okr-target">'+select('Nível do objetivo','scope',scope)+select('Empresa','companyId','Sanepav/Beta Clean')+department+'<div data-okr-owner>'+select('Responsável (opcional)','ownerId','Sem responsável individual')+'</div></div><p class="lxp-note" id="okrTargetHint">Objetivo corporativo. Consulte as permissões de acordo com seu perfil.</p>'+field('Início','startsOn','2026-11-26','date')+field('Fim','endsOn','2026-11-26','date')+'<div id="okrKRs">'+kr*num+'</div><button type="button" class="lxp-btn" data-okr13="add-kr">Adicionar resultado-chave</button><div class="lxp-heading-actions"><button type="submit" class="lxp-btn primary">Confirmar</button><button type="button" class="lxp-btn" data-okr13="cancel">Cancelar</button></div><p role="alert" id="okr13Error"></p></form></section></div></dialog>'
count=0
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
 for w,h in [(320,568),(390,844),(667,921),(768,700),(1064,784),(1440,900)]:
  page=b.new_page(viewport={'width':w,'height':h})
  for scope in ['Empresa','Departamento','Colaborador(a)']:
   for route in [True,False]:
    for num in [1,3]:
     page.set_content('<style>'+legacy+css+'</style>'+fixture(scope,num,route));page.evaluate('modal.showModal()')
     result=page.evaluate('''() => {const d=document.querySelector('#modal'),f=document.querySelector('#okr13Form'),kr=f.querySelector('fieldset'),l=kr.querySelector('legend'),first=kr.querySelector('label'),r=x=>x.getBoundingClientRect(),a=r(d),k=r(kr),g=r(l),v=r(first),owner=r(f.querySelector('[data-okr-owner]')),target=r(f.querySelector('.okr-target')),btn=f.querySelector('[type=submit]');btn.scrollIntoView({block:'end'});let c=r(btn);return {inside:a.left>=0&&a.right<=innerWidth+1&&a.top>=0&&a.bottom<=innerHeight+1,legendInside:g.top>=k.top+3&&g.left>=k.left+3&&g.right<=k.right-3,legendSeparate:g.bottom<=v.top,ownerWidth:f.querySelector('[data-okr-department]').hidden?Math.abs(owner.width-target.width)<2:true,noArt:!getComputedStyle(d).backgroundImage.includes('url('),noOverflow:d.scrollWidth<=d.clientWidth+1,footerVisible:c.left>=a.left&&c.right<=a.right&&c.top>=a.top&&c.bottom<=a.bottom+1,footerClickable:document.elementFromPoint(c.x+c.width/2,c.y+c.height/2)===btn,numberFields:innerWidth>600?Math.abs(r(kr.querySelector('[name=baseline]')).top-r(kr.querySelector('[name=target]')).top)<2:true,dates:innerWidth>600?Math.abs(r(f.querySelector('[name=startsOn]')).top-r(f.querySelector('[name=endsOn]')).top)<2:true}}''')
     assert all(result.values()),(w,scope,route,num,result);count+=len(result)
     if w==667 and scope=='Empresa' and route and num==1:
      page.evaluate('modal.scrollTop=0');page.screenshot(path=str(ROOT/'GUIA/previa-okr.png'))
  page.close()
 b.close()
print(f'{count} verificações de layout aprovadas (fixture isolada, seis resoluções, três escopos, um e três KRs, antes/depois do decorador).')
